import json
import os
import re
import sys


def parse_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None
    if re.match(r"^\d{8}$", val):
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if re.match(r"^\d{4}-\d{2}-\d{2}$", val):
        return val
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports
    doc_name = "fda_enforcement_reports"
    json_path = os.path.join(packet_dir, f"{doc_name}.json")

    records_by_entity = {}
    if os.path.exists(json_path):
        with open(json_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_entity.setdefault(recall_num.strip(), []).append(item)

    fact_field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    output = {}

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        facts_to_extract = facts_schema.get(rule_id, [])

        pair_result = {}
        matching_records = records_by_entity.get(entity, [])

        for fact in facts_to_extract:
            field_key = fact_field_map.get(fact)
            if not field_key:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for rec in matching_records:
                raw_val = rec.get(field_key)
                norm_val = parse_date(raw_val)
                if norm_val is not None:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact] = "CONFLICT"
            else:
                val = next(iter(values))
                pair_result[fact] = [val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=1))


if __name__ == "__main__":
    main()
