import sys
import os
import json
from collections import defaultdict

FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

def format_date(d_str):
    if not d_str:
        return None
    d_str = str(d_str).strip()
    if not d_str or d_str.upper() in ("N/A", "NONE", "UNKNOWN"):
        return None
    if len(d_str) == 8 and d_str.isdigit():
        return f"{d_str[:4]}-{d_str[4:6]}-{d_str[6:8]}"
    if len(d_str) == 10 and d_str[4] == '-' and d_str[7] == '-':
        return d_str
    return d_str

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports
    records_by_recall_number = defaultdict(list)
    fda_file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    if os.path.exists(fda_file_path):
        with open(fda_file_path, "r", encoding="utf-8") as f:
            fda_data = json.load(f)
            records = fda_data.get("results", []) if isinstance(fda_data, dict) else fda_data
            for rec in records:
                rn = rec.get("recall_number")
                if rn:
                    records_by_recall_number[str(rn).strip()].append(rec)

    pairs = manifest.get("pairs", [])
    manifest_facts = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity_clean = entity.strip()
        facts = manifest_facts.get(rule_id, [])

        pair_result = {}
        rule_fact_defs = FACT_MAP.get(rule_id, {})

        for fact in facts:
            if fact not in rule_fact_defs:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_name = rule_fact_defs[fact]
            records = records_by_recall_number.get(entity_clean, [])

            values = []
            for rec in records:
                raw_val = rec.get(field_name)
                formatted = format_date(raw_val)
                if formatted:
                    values.append(formatted)

            unique_vals = list(set(values))
            if not unique_vals:
                pair_result[fact] = "ABSENT"
            elif len(unique_vals) > 1:
                pair_result[fact] = "CONFLICT"
            else:
                pair_result[fact] = [unique_vals[0], doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
