    norm = fact_name.lower().strip()
    candidate_keys = []
    if norm in FIELD_MAP:
        candidate_keys.append(FIELD_MAP[norm])
    cand = norm.replace(" ", "_")
    candidate_keys.extend([cand, f"recall_{cand}", f"center_{cand}"])

    for key in candidate_keys:
        if key in record:
            return record[key]
    return None

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    # Load fda_enforcement_reports if available
    doc_name = "fda_enforcement_reports"
    json_path = os.path.join(packet_dir, f"{doc_name}.json")
    records_by_recall = {}

    if os.path.exists(json_path):
        with open(json_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", []) if isinstance(data, dict) else data
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_recall.setdefault(str(recall_num).strip(), []).append(item)

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        fact_names = facts_schema.get(rule_id, [])

        matched_records = records_by_recall.get(entity, [])
        pair_res = {}

        for fact in fact_names:
            vals = set()
            for rec in matched_records:
                raw_val = resolve_field(fact, rec)
                fval = format_date(raw_val)
                if fval is not None:
                    vals.add(fval)

            if len(vals) == 0:
                pair_res[fact] = "ABSENT"
            elif len(vals) == 1:
                pair_res[fact] = [next(iter(vals)), doc_name]
            else:
                pair_res[fact] = "CONFLICT"

        output[pair] = pair_res

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

